const std = @import("std"); const stor = @import("taskstore"); const time = @import("tasktime"); const armz = @import("taskarm"); const spaw = @import("spawn"); const regi = @import("registry"); const supe = @import("tasksuper"); const prob = @import("taskprobe"); const conf = @import("store"); const stre = @import("stream");
const tktickbase = @import("tk-tick-base.zig"); const ArmeReje = tktickbase.ArmeReje; const CF = tktickbase.CF; const CatcReqz = tktickbase.CatcReqz; const ChaiFini = tktickbase.ChaiFini; const ChaiRunz = tktickbase.ChaiRunz; const ChaiView = tktickbase.ChaiView; const Jobz = tktickbase.Jobz; const PollReqz = tktickbase.PollReqz; const RunzLast = tktickbase.RunzLast; const RunzLastReco = tktickbase.RunzLastReco; const RunzResu = tktickbase.RunzResu; const RunzSlot = tktickbase.RunzSlot; const StarReqz = tktickbase.StarReqz; const chaiResu = tktickbase.chaiResu; const finiPush = tktickbase.finiPush; const intoDupe = tktickbase.intoDupe; const jobzClon = tktickbase.jobzClon; const jobzFill = tktickbase.jobzFill; const logzDirz = tktickbase.logzDirz; const logzRota = tktickbase.logzRota; const membNext = tktickbase.membNext; const nowzMsec = tktickbase.nowzMsec; const plusPick = tktickbase.plusPick; const poolCoun = tktickbase.poolCoun; const poolPick = tktickbase.poolPick; const recoLast = tktickbase.recoLast; const ringDrop = tktickbase.ringDrop; const ringNote = tktickbase.ringNote; const ringSeal = tktickbase.ringSeal; const taskFind = tktickbase.taskFind;
const Sche = @import("tk-task-tick.zig").Sche;
pub fn stepRingNewz(self: *Sche, chai: *ChaiRunz, step: []const u8, nowz_msec: i64) ?*regi.Ring { if (!self.chai_ring or chai.ring_coun >= chai.ring_list.len) return null; const ring = regi.Ring.crea(self.gpaz, step, self.root, chai.name(), nowz_msec) catch return null; chai.ring_list[chai.ring_coun] = ring; chai.ring_coun += 1; ring.reta(); return ring; }
pub fn chaiSlot(self: *Sche, iden: []const u8) ?*ChaiRunz { for (&self.chai) |*chai| if (chai.used and std.mem.eql(u8, chai.name(), iden)) return chai; for (&self.chai) |*chai| if (!chai.used) { chai.* = .{ .used = true }; chai.iden_leng = intoDupe(&chai.iden_buff, iden).len; return chai; }; return null; }
pub fn plusDraw(self: *Sche, iozz: std.Io, plus: ?std.json.Value) i64 { if (self.prng == null) self.prng = std.Random.DefaultPrng.init(@bitCast(nowzMsec(iozz))); return plusPick(self.prng.?.random(), plus); }
pub fn chaiSave(self: *Sche, iozz: std.Io, chai: *const ChaiRunz) void { if (!self.chai_pers) return; var aren = std.heap.ArenaAllocator.init(self.gpaz); defer aren.deinit(); stor.chaiStatWrit(aren.allocator(), iozz, chai.name(), .{ .inde = @intCast(chai.indx), .ranz = chai.ranz, .fail = chai.fail, .next_msec = chai.next_msec, .star_msec = chai.star_msec }); }
pub fn chaiForg(self: *Sche, iozz: std.Io, chai: *const ChaiRunz) void { if (!self.chai_pers) return; var aren = std.heap.ArenaAllocator.init(self.gpaz); defer aren.deinit(); stor.chaiStatClea(aren.allocator(), iozz, chai.name()); }
pub fn virtFill(self: *Sche, jobz: *Jobz, iden: []const u8, chai: stor.Task) bool { var buff: [2048]u8 = undefined; var fixd = std.heap.FixedBufferAllocator.init(&buff); const cmdz = (stor.autoRunz(fixd.allocator(), self.root, iden) catch null) orelse return false; var virt = chai; virt.type = "hand"; virt.run = cmdz; virt.sche = null; virt.ids = null; virt.plus = null; virt.catc = null; jobzFill(jobz, iden, virt); return true; }
pub fn chaiTick(self: *Sche, iozz: std.Io, nowz: time.Local, nowz_msec: i64, pend: []const supe.Done, list: []const stor.Task, duez: []Jobz, duez_coun: *usize, fini: []ChaiFini, fini_coun: *usize) void { for (self.arme) |*arme| { if (!arme.isChain()) continue; const chai_task = taskFind(list, arme.id) orelse continue; const idsz = chai_task.ids orelse continue; const chai = self.chaiSlot(arme.id) orelse continue; const hand = arme.takeChainHand(); const trig = arme.due(iozz, nowz, nowz_msec, self.sola); if (!chai.seen) { chai.seen = true; if (self.chai_pers) { var aren = std.heap.ArenaAllocator.init(self.gpaz); defer aren.deinit(); if (stor.chaiStatRead(aren.allocator(), iozz, arme.id)) |stat| chaiResu(chai, stat); } } if (chai.abor) { chai.abor = false; if (hand) _ = arme.requestHand(); if (chai.runn) { finiPush(chai, nowz_msec, chai_task.noLog orelse false, true, fini, fini_coun); self.done.push(arme.id, false, 0); self.chaiForg(iozz, chai); chai.runn = false; chai.wait = false; } continue; } if (chai.paus and chai.runn) { const delt = nowz_msec - chai.paus_last; chai.paus_last = nowz_msec; chai.dead_msec += delt; chai.next_msec += delt; } if (!chai.runn) { chai.paus = false; var goz = hand or trig; if (arme.chainBoots() and !chai.boot) goz = true; chai.boot = true; if (!goz) continue; chai.runn = true; chai.wait = true; chai.indx = membNext(list, idsz, 0); chai.star_msec = nowz_msec; chai.next_msec = nowz_msec + (if (hand) @as(i64, 0) else @as(i64, chai_task.dela orelse 0) * 60_000); chai.ranz = 0; chai.fail = 0; chai.fail_leng = 0; ringDrop(chai); self.chaiSave(iozz, chai); if (self.chai_pers and (chai_task.catc orelse 0) > 0) { var temp = std.heap.ArenaAllocator.init(self.gpaz); defer temp.deinit(); stor.fireLastWrit(temp.allocator(), iozz, arme.id, time.localNow().minute_stamp); } arme.markFired(nowz_msec); _ = self.fire_coun.fetchAdd(1, .monotonic); } if (chai.runn and !chai.wait and chai.indx >= idsz.len) chai.wait = true; if (!chai.wait) { const curr = idsz[chai.indx]; var donz = false; var okzz = true; var skip = false; for (pend) |*done| if (std.mem.eql(u8, done.name(), curr)) { donz = true; okzz = done.okzz; skip = done.skip; break; }; if (!donz and nowz_msec >= chai.dead_msec) { donz = true; okzz = false; } if (donz) { chai.ranz += 1; if (!okzz) { chai.fail += 1; if (chai.fail_leng > 0) chai.fail_leng += intoDupe(chai.fail_buff[chai.fail_leng..], ", ").len; chai.fail_leng += intoDupe(chai.fail_buff[chai.fail_leng..], curr).len; } chai.indx = membNext(list, idsz, chai.indx + 1); chai.wait = true; chai.next_msec = nowz_msec + (if (skip) 0 else self.plusDraw(iozz, chai_task.plus)); self.chaiSave(iozz, chai); } } if (!chai.wait) { if (chai.paus) _ = self.regz.pausSetz(iozz, chai.step_buff[0..chai.step_leng], true, nowz_msec); continue; } if (chai.indx >= idsz.len) { finiPush(chai, nowz_msec, chai_task.noLog orelse false, false, fini, fini_coun); self.done.push(arme.id, chai.fail == 0, 0); self.chaiForg(iozz, chai); chai.runn = false; chai.wait = false; continue; } if (chai.paus or nowz_msec < chai.next_msec or duez_coun.* >= duez.len) continue; const jobz = &duez[duez_coun.*]; if (taskFind(list, idsz[chai.indx])) |memb| { jobzFill(jobz, idsz[chai.indx], memb); } else if (!self.virtFill(jobz, idsz[chai.indx], chai_task)) { chai.dead_msec = 0; chai.wait = false; continue; } jobz.chai = true; jobz.teez = self.stepRingNewz(chai, idsz[chai.indx], nowz_msec); chai.step_leng = intoDupe(&chai.step_buff, idsz[chai.indx]).len; const trys: i64 = @as(i64, jobz.retr) + 1; chai.dead_msec = nowz_msec + @as(i64, jobz.time_msec) * trys + @as(i64, jobz.retr) * CF.retr_maxz_msec + CF.chai_slac_msec; chai.wait = false; duez_coun.* += 1; } }
pub fn chaiLogz(self: *Sche, iozz: std.Io, fini: *const ChaiFini) void { if (fini.nozz_logz) return; var jobz: Jobz = .{}; jobz.iden = intoDupe(&jobz.iden_buff, fini.iden_buff[0..fini.iden_leng]); const firs = fini.fail_buff[0..fini.fail_leng]; jobz.runz = if (fini.abor) std.fmt.bufPrint(&jobz.runz_buff, "chain: aborted by user ({d} ran, {d} failed)", .{ fini.ranz, fini.fail }) catch "" else if (fini.fail == 0) std.fmt.bufPrint(&jobz.runz_buff, "chain: {d} ran, 0 failed", .{fini.ranz}) catch "" else if (firs.len == 0) std.fmt.bufPrint(&jobz.runz_buff, "chain: {d} ran, {d} failed", .{ fini.ranz, fini.fail }) catch "" else std.fmt.bufPrint(&jobz.runz_buff, "chain: {d} ran, {d} failed — failed: {s}", .{ fini.ranz, fini.fail, firs }) catch ""; self.fireLogz(iozz, &jobz, .{ .code = if (fini.fail == 0 and !fini.abor) 0 else 1, .elap_msec = fini.elap_msec }) catch |erro| { if (!self.logz_warn.swap(true, .monotonic)) { std.debug.print("  warn: task log write failed ({t}) — tasks still fire\n", .{erro}); } }; }
pub fn chaiView(self: *Sche, iozz: std.Io, iden: []const u8) ?ChaiView { for (&self.chai) |*chai| { if (!chai.used or !chai.runn or !std.mem.eql(u8, chai.name(), iden)) continue; const left = if (chai.wait) @max(chai.next_msec - nowzMsec(iozz), 0) else 0; return .{ .wait = chai.wait, .indx = chai.indx, .ranz = chai.ranz, .fail = chai.fail, .next_minu = @divTrunc(left + 59_999, 60_000), .star_msec = chai.star_msec, .next_msec = chai.next_msec, .paus = chai.paus }; } return null; }
pub fn chaiAbor(self: *Sche, iozz: std.Io, iden: []const u8) bool { var step_buff: [128]u8 = undefined; var step_leng: usize = 0; { self.mute.lock(iozz) catch return false; defer self.mute.unlock(iozz); const chai = for (&self.chai) |*item| { if (item.used and item.runn and std.mem.eql(u8, item.name(), iden)) break item; } else return false; chai.abor = true; if (!chai.wait) step_leng = intoDupe(&step_buff, chai.step_buff[0..chai.step_leng]).len; } if (step_leng == 0) return true; const step = step_buff[0..step_leng]; { self.queu_mute.lock(iozz) catch return true; defer self.queu_mute.unlock(iozz); self.abor_leng = intoDupe(&self.abor_buff, step).len; var indx: usize = 0; while (indx < self.queu.items.len) { const jobz = self.queu.items[indx]; if (jobz.chai and std.mem.eql(u8, jobz.iden, step)) { _ = self.queu.orderedRemove(indx); if (jobz.teez) |teez| ringSeal(iozz, teez, -1, 0); self.jobzFree(jobz); } else indx += 1; } } if (!self.regz.idenKill(iozz, step)) _ = self.aborTake(iozz, step); return true; }
pub fn chaiPaus(self: *Sche, iozz: std.Io, iden: []const u8, onzz: bool) regi.PausCode { var step_buff: [128]u8 = undefined; var step_leng: usize = 0; const nowz = nowzMsec(iozz); { self.mute.lock(iozz) catch return .fail; defer self.mute.unlock(iozz); const chai = for (&self.chai) |*item| { if (item.used and item.runn and std.mem.eql(u8, item.name(), iden)) break item; } else return .none; if (chai.paus == onzz) return .same; chai.paus = onzz; if (onzz) { chai.paus_last = nowz; } else { const delt = nowz - chai.paus_last; chai.dead_msec += delt; chai.next_msec += delt; } if (!chai.wait) step_leng = intoDupe(&step_buff, chai.step_buff[0..chai.step_leng]).len; } if (step_leng > 0) _ = self.regz.pausSetz(iozz, step_buff[0..step_leng], onzz, nowz); return .okzz; }
pub fn chaiRing(self: *Sche, iozz: std.Io, iden: []const u8) ?*regi.Ring { const atzz = std.mem.lastIndexOfScalar(u8, iden, '~') orelse return null; const numb = std.fmt.parseInt(usize, iden[atzz + 1 ..], 10) catch return null; self.mute.lock(iozz) catch return null; defer self.mute.unlock(iozz); for (&self.chai) |*chai| { if (!chai.used or !std.mem.eql(u8, chai.name(), iden[0..atzz])) continue; if (numb == 0 or numb > chai.ring_coun) return null; const ring = chai.ring_list[numb - 1] orelse return null; ring.reta(); return ring; } return null; }
pub fn chaiJobzWrit(self: *Sche, iozz: std.Io, wrtr: *std.Io.Writer, comm: bool) !void { try self.mute.lock(iozz); defer self.mute.unlock(iozz); var firs = !comm; for (&self.chai) |*chai| { if (!chai.used) continue; for (chai.ring_list[0..chai.ring_coun], 1..) |slot, numb| { const ring = slot orelse continue; if (!firs) try wrtr.writeAll(","); firs = false; try wrtr.print("{{\"id\":\"{s}~{d}\",\"cmd\":", .{ chai.name(), numb }); try std.json.Stringify.encodeJsonString(ring.cmdz, .{}, wrtr); try wrtr.writeAll(",\"cwd\":\"\",\"tab\":"); try std.json.Stringify.encodeJsonString(chai.name(), .{}, wrtr); try wrtr.print(",\"started\":{d},\"run\":{d},\"keep\":true,\"done\":{},\"bytes\":{d},\"chain\":true}}", .{ ring.star_msec, chai.star_msec, ring.doneChec(iozz), ring.size(iozz) }); } } }
pub fn aborTake(self: *Sche, iozz: std.Io, iden: []const u8) bool { self.queu_mute.lock(iozz) catch return false; defer self.queu_mute.unlock(iozz); if (self.abor_leng == 0 or !std.mem.eql(u8, self.abor_buff[0..self.abor_leng], iden)) return false; self.abor_leng = 0; return true; }
